    private readonly ActorDefinitionOperations _definitions=new();private readonly ActorTimelineOperations _timeline=new();private readonly ActorRuntimeOperations _clips=new();private readonly ActorDataOperations _data=new();private readonly TimelinePhysicsOperations _physics=new();private readonly ActorAudioSystemOperations _audio=new();
    private static RefCounted Model(Control owner)=>owner.Get("model").As<RefCounted>();private static RefCounted Physics(Control owner)=>owner.Get("physics").As<RefCounted>();private static Settings Runtimes(Control owner)=>owner.Get("_runtimes").AsGodotDictionary();private static GArray Actors(Control owner)=>Model(owner).Get("actors").AsGodotArray();private static GArray Clips(Control owner)=>Model(owner).Get("clips").AsGodotArray();private static Control Canvas(Control owner)=>owner.Get("canvas").As<Control>();private static double Time(Control owner)=>Canvas(owner).Get("playhead").AsDouble();private static bool Playing(Control owner)=>owner.Get("playing").AsBool();private static bool Recording(Control owner)=>owner.Get("audio_recorder").AsGodotObject().Get("recording").AsBool()||owner.Get("screen_recorder").AsGodotObject().Get("recording").AsBool();
    public Node3D? runtime_for_clip(Control owner,string id){var runtimes=Runtimes(owner);if(!runtimes.TryGetValue(id,out var value))return null;var node=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Node3D:null;if(GodotObject.IsInstanceValid(node))return node;runtimes.Remove(id);return null;}
    public void setup_runtime_holder(Control owner){var viewport=owner.GetNodeOrNull<SubViewport>("../../../../World/SubViewport");if(viewport==null)return;var camera=viewport.GetNodeOrNull<Camera3D>("Freecam/Head/Camera3D");if(camera!=null){camera.CullMask|=2;camera.MakeCurrent();}var holder=new Node3D{Name="ActorRuntimes"};owner.Set("runtime_holder",holder);viewport.AddChild(holder);var gizmo=new ActorUIGizmo();owner.Set("viewport_gizmo",gizmo);gizmo.Set("editor",owner);var display=owner.GetNodeOrNull<TextureRect>("../HSplitContainer/VBoxContainer/Viewport");if(display!=null){gizmo.Set("display",display);display.AddChild(gizmo);}else{var overlay=new CanvasLayer{Layer=100};holder.AddChild(overlay);overlay.AddChild(gizmo);}sync_runtimes(owner);}
    public void connect_shader_editor(Control owner){var editor=owner.GetTree().GetFirstNodeInGroup("shader_code_editor");if(editor==null||!editor.HasSignal("shader_changed"))return;var callback=new Callable(owner,"_on_shader_source_changed");if(!editor.IsConnected("shader_changed",callback))editor.Connect("shader_changed",callback);}
    public void refresh_saved_shader(Control owner,Variant source){on_model_changed(owner);var inspector=owner.Get("inspector").As<Control>();if(inspector!=null)inspector.Call("refresh_shader_source",source);}
    public void recreate_runtimes(Control owner){_physics.dispose(Physics(owner),false);if(owner.Get("runtime_holder").As<Node3D>()==null)return;var runtimes=Runtimes(owner);foreach(var value in runtimes.Values){var runtime=value.AsGodotObject() as Node;if(GodotObject.IsInstanceValid(runtime)&&runtime!.GetParent()!=null)runtime.GetParent().RemoveChild(runtime);}foreach(var value in runtimes.Values){var runtime=value.AsGodotObject() as Node;if(GodotObject.IsInstanceValid(runtime))runtime!.QueueFree();}runtimes.Clear();owner.Get("_particle_seek_states").AsGodotDictionary().Clear();sync_runtimes(owner);}
    public void on_model_changed(Control owner){_physics.mark_dirty(Physics(owner));_timeline.validate_focus(Model(owner));sync_runtimes(owner);owner.Call("_refresh");}
    public void sync_runtimes(Control owner)
    {
        var holder=owner.Get("runtime_holder").As<Node3D>();if(holder==null)return;var actors=Actors(owner);var clips=Clips(owner);var runtimes=Runtimes(owner);int count=Math.Min(actors.Count,clips.Count);var live=new HashSet<string>();var byActor=new Dictionary<string,string>();for(int i=0;i<count;i++){var actor=actors[i].As<Resource>();var clip=clips[i].As<Resource>();string id=clip.Get("id").AsString();live.Add(id);byActor[actor.Get("id").AsString()]=id;if(!runtimes.ContainsKey(id)){var definition=_definitions.get_definition(owner.Get("registry").As<RefCounted>(),actor.Get("type_id").AsStringName());var runtime=definition!=null?_definitions.create_runtime(definition,actor):null;if(runtime!=null){holder.AddChild(runtime);runtimes[id]=runtime;}}}for(int i=0;i<count;i++){var actor=actors[i].As<Resource>();var runtime=runtime_for_clip(owner,clips[i].As<Resource>().Get("id").AsString());if(runtime==null)continue;Node3D? parent=null;if(byActor.TryGetValue(actor.Get("parent_id").AsString(),out var id))parent=runtime_for_clip(owner,id);var target=parent!=null?parent.Call("parenting_node").As<Node>():holder;if(target!=null&&runtime.GetParent()!=target){runtime.GetParent()?.RemoveChild(runtime);target.AddChild(runtime);}}foreach(var id in runtimes.Keys.ToArray()){if(live.Contains(id.AsString()))continue;var runtime=runtimes[id].AsGodotObject() as Node;if(GodotObject.IsInstanceValid(runtime))runtime!.Free();runtimes.Remove(id);}evaluate_runtimes(owner);
    }
    public int actor_depth(Control owner,Resource actor){int depth=0;var parent=_timeline.actor_for_id(Model(owner),actor.Get("parent_id").AsString());var visited=new HashSet<string>();while(parent!=null&&visited.Add(parent.Get("id").AsString())){depth++;parent=_timeline.actor_for_id(Model(owner),parent.Get("parent_id").AsString());}return depth;}
    public void evaluate_runtimes(Control owner)
    {
        var audio=owner.Get("audio_system").As<Node>();var model=Model(owner);double time=Time(owner);if(Recording(owner)){owner.Call("_route_timeline_audio");if(owner.Call("_recording_timeline_audio").AsBool()){model.Set("playhead_time",time);if(audio!=null)_audio.synchronize(audio,model,time,Playing(owner));}else if(audio!=null)foreach(var player in audio.Get("players").AsGodotDictionary().Values)player.As<AudioStreamPlayer>().Stop();return;}if(audio!=null&&audio.Get("output_bus").AsString()!="Master")_audio.set_output_bus(audio,"Master");model.Set("playhead_time",time);_physics.restore_visuals(Physics(owner));var actors=Actors(owner);var clips=Clips(owner);int count=Math.Min(actors.Count,clips.Count);for(int i=0;i<count;i++)actors[i].As<Resource>().Set("animation_time",_clips.local_time(clips[i].As<Resource>(),time));if(audio!=null)_audio.synchronize(audio,model,time,Playing(owner));var indices=Enumerable.Range(0,count).Select(i=>(Index:i,Depth:actor_depth(owner,actors[i].As<Resource>()))).OrderBy(pair=>pair.Depth).Select(pair=>pair.Index).ToArray();foreach(int i in indices){var clip=clips[i].As<Resource>();var runtime=runtime_for_clip(owner,clip.Get("id").AsString());if(runtime!=null)_clips.evaluate_clip(runtime,clip,time,new Settings());}var bases=new Dictionary<string,Transform3D>();foreach(int i in indices){var runtime=runtime_for_clip(owner,clips[i].As<Resource>().Get("id").AsString());if(runtime==null)continue;var actor=runtime.Get("actor").As<Resource>();if(actor.Get("values").AsGodotDictionary().ContainsKey("model_rigid_bone"))bases[actor.Get("id").AsString()]=runtime.Call("remote_transform").AsTransform3D();if(runtime.HasMethod("apply_rig_attachment"))runtime.Call("apply_rig_attachment");}apply_remote_transforms(owner);var physics=Physics(owner);_physics.evaluate(physics,model,Runtimes(owner),time,240);foreach(int i in indices){var runtime=runtime_for_clip(owner,clips[i].As<Resource>().Get("id").AsString());if(runtime==null||physics.Get("prototypes").AsGodotDictionary().Count==0||!runtime.HasMethod("apply_rig_attachment"))continue;string id=runtime.Get("actor").As<Resource>().Get("id").AsString();if(bases.TryGetValue(id,out var transform)){if(physics.Get("display_states").AsGodotDictionary().GetValueOrDefault(id,new Settings()).AsGodotDictionary().GetValueOrDefault("initialized",false).AsBool())continue;runtime.Call("apply_remote_transform",transform,true,true,true);}runtime.Call("apply_rig_attachment");}if(!owner.Get("exporting").AsBool()){sync_particle_seeks(owner);var camera=owner.GetNodeOrNull<Camera3D>("../../../../World/SubViewport/Freecam/Head/Camera3D");if(camera!=null&&!camera.IsCurrent())camera.MakeCurrent();}update_camera_overlays(owner);
    }
    public void update_camera_overlays(Control owner){var actors=Actors(owner);var clips=Clips(owner);for(int i=0;i<Math.Min(actors.Count,clips.Count);i++){if(actors[i].As<Resource>().Get("type_id").AsString()!="camera_3d")continue;var runtime=runtime_for_clip(owner,clips[i].As<Resource>().Get("id").AsString());if(runtime!=null&&runtime.HasMethod("update_camera_overlay"))runtime.Call("update_camera_overlay");}}
    public void sync_particle_seeks(Control owner){var actors=Actors(owner);var clips=Clips(owner);var states=owner.Get("_particle_seek_states").AsGodotDictionary();for(int i=0;i<Math.Min(actors.Count,clips.Count);i++){var actor=actors[i].As<Resource>();string type=actor.Get("type_id").AsString();if(type is not ("particles_2d" or "particles_3d"))continue;var clip=clips[i].As<Resource>();var runtime=runtime_for_clip(owner,clip.Get("id").AsString());if(runtime==null)continue;var particle=runtime.Get(type=="particles_2d"?"particles_2d":"content").AsGodotObject() as Node;if(particle is not (GpuParticles2D or GpuParticles3D))continue;var id=clip.Get("id");if(!runtime.Get("active").AsBool()||!particle.Get("emitting").AsBool()){states.Remove(id);continue;}if(Playing(owner)){particle.Set("speed_scale",1.0);states.Remove(id);continue;}double local=Math.Max(0,_clips.local_time(clip,Time(owner)));long signature=runtime.Get("_particle_settings_hash").AsInt64();var previous=states.GetValueOrDefault(id,new Settings()).AsGodotDictionary();particle.Set("speed_scale",0.0);if(previous.GetValueOrDefault("instance",-1L).AsInt64()==unchecked((long)particle.GetInstanceId())&&Mathf.IsEqualApprox(previous.GetValueOrDefault("time",-1.0).AsDouble(),local)&&previous.GetValueOrDefault("settings",-1L).AsInt64()==signature)continue;particle.Call("restart");double lifetime=Math.Max(.05,particle.Get("lifetime").AsDouble()),seek=particle.Get("one_shot").AsBool()?local:local%(lifetime*2);if(seek>0&&particle.HasMethod("request_particles_process"))particle.Call("request_particles_process",seek);states[id]=new Settings{["instance"]=particle.GetInstanceId(),["time"]=local,["settings"]=signature};}}
    public void apply_remote_transforms(Control owner){var actors=Actors(owner);var clips=Clips(owner);for(int i=0;i<Math.Min(actors.Count,clips.Count);i++){var remote=actors[i].As<Resource>();if(remote.Get("type_id").AsString()!="remote_transform"||!_clips.contains_time(clips[i].As<Resource>(),Time(owner)))continue;var target=_timeline.actor_for_id(Model(owner),_data.get_value(remote,"remote_actor","").AsString());if(target==null||target==remote)continue;var source=runtime_for_clip(owner,clips[i].As<Resource>().Get("id").AsString());var targetClip=_timeline.clip_for_actor_id(Model(owner),target.Get("id").AsString());var destination=targetClip!=null?runtime_for_clip(owner,targetClip.Get("id").AsString()):null;if(source==null||destination==null||!source.Call("supports_remote_transform").AsBool()||!destination.Call("supports_remote_transform").AsBool())continue;destination.Call("apply_remote_transform",source.Call("remote_transform"),_data.get_value(remote,"set_position",true),_data.get_value(remote,"set_rotation",true),_data.get_value(remote,"set_scale",true));}}
